const SUTRA_DISTRICT_FACTS={"Agra":"Taj Mahal, Mughal-era architecture and marble inlay traditions.","Varanasi":"Ganga ghats, temple lanes, weaving and riverfront cultural life.","Lucknow":"Awadhi architecture, chikankari craft and courtly food traditions.","Prayagraj":"Sangam river landscape, pilgrimage routes and historic institutions.","Jaipur":"Amber, Hawa Mahal, Jantar Mantar and block-printing traditions.","Udaipur":"Lake Pichola, City Palace and Mewar court traditions.","Jaisalmer":"Living fort, desert routes, textiles and folk music traditions.","Jodhpur":"Mehrangarh, blue-city neighbourhoods and Marwar foodways.","Hyderabad":"Charminar, Golconda, Qutb Shahi heritage and Deccani food.","Warangal":"Kakatiya monuments, fort walls and temple sculpture.","Mulugu":"Ramappa and forest-edge heritage landscapes.","Nizamabad":"Deccan forts, temples and regional food traditions.","Hampi":"Vijayanagara ruins, boulder landscapes and living pilgrimage culture.","Mysuru":"Mysore Palace, painting, silk and Dasara traditions.","Bengaluru":"Urban culture, old markets and a fast-growing food scene.","Coorg":"Coffee estates, Kodava food and hill-country traditions.","Bhubaneswar":"Temple city architecture, old-town heritage and Odia food.","Puri":"Jagannath heritage, Mahaprasad and coastal pilgrimage culture.","Konark":"Sun Temple, stone carving and coastal cultural routes.","Cuttack":"Silver filigree, Barabati heritage and river-city traditions.","Mumbai":"Gateway of India, colonial-era city fabric and coastal food culture.","Pune":"Shaniwar Wada, Peshwa-era history and contemporary cultural life.","Chhatrapati Sambhaji Nagar":"Ajanta-Ellora gateway, Deccan history and cave heritage.","Nashik":"Godavari riverfront, vineyards and pilgrimage heritage.","Ahmedabad":"Pols, textile traditions, Sabarmati heritage and stepwells nearby.","Kutch":"Embroidery, weaving, desert villages and craft communities.","Vadodara":"Palaces, museums and Gujarat’s arts institutions.","Surat":"Textiles, diamond trade and Gujarati food traditions.","Kochi":"Fort Kochi, spice-route history, performance and coastal food.","Alappuzha":"Backwaters, coir craft and houseboat landscapes.","Munnar":"Tea estates, mountain ecology and plantation heritage.","Thiruvananthapuram":"Temple heritage, museums and Kerala cultural institutions.","Amritsar":"Golden Temple, Jallianwala Bagh and Punjabi food traditions.","Ludhiana":"Textiles, bicycle industry and Punjabi urban culture.","Patiala":"Qila Mubarak, Patiala gharana and royal food traditions.","Jalandhar":"Rural Punjab traditions, sports culture and local craft.","Kolkata":"Colonial-era neighbourhoods, literature, Durga Puja and Bengali food.","Darjeeling":"Tea estates, Himalayan views and Gorkha cultural traditions.","Murshidabad":"Nawabi-era architecture, silk and riverine heritage.","Siliguri":"Gateway to the Himalayan foothills with tea and market culture.","Chennai":"Temple traditions, classical arts, Marina and Tamil food culture.","Madurai":"Meenakshi Temple, jasmine markets and Tamil cultural traditions.","Thanjavur":"Chola temple heritage, bronze casting and classical arts.","Coimbatore":"Textiles, industry and access to western Tamil Nadu hill landscapes.","Guwahati":"Kamakhya, Brahmaputra riverfront and Assamese cultural life.","Jorhat":"Tea heritage and Upper Assam cultural landscapes.","Majuli":"Satras, mask-making, island communities and Vaishnavite traditions.","Sivasagar":"Ahom-era monuments, tanks and historic landscapes.","Patna":"Ganga riverfront, ancient learning routes and Bihar urban culture.","Gaya":"Buddhist pilgrimage routes and sacred landscapes.","Nalanda":"Ancient university heritage and Buddhist learning traditions.","Madhubani":"Madhubani painting, folk art and Mithila cultural traditions.","Panaji":"Portuguese-era quarters, riverfronts and Goan festivals.","North Goa":"Beaches, heritage villages, churches and contemporary Goan culture.","South Goa":"Coastal villages, churches and slower local food traditions.","Margao":"Market culture, Indo-Portuguese heritage and Goan cuisine.","Shimla":"Colonial-era hill architecture and Himalayan mountain culture.","Kullu":"Valley temples, shawl weaving and mountain festivals.","Kangra":"Kangra Fort, miniature painting and Dhauladhar landscapes.","Chamba":"Temple architecture, Chamba rumal embroidery and mountain traditions.","Ranchi":"Tribal culture, forests and Jharkhand urban heritage.","Deoghar":"Baidyanath temple heritage and pilgrimage culture.","East Singhbhum":"Industrial history alongside tribal and forest landscapes.","Hazaribagh":"Forest landscapes, rock art and regional craft traditions.","Bhopal":"Lakes, museums and a layered Central Indian cultural landscape.","Indore":"Food streets, Rajwada and the Malwa cultural region.","Khajuraho":"Temple sculpture and heritage architecture.","Gwalior":"Hilltop fort, music traditions and Scindia-era history.","Imphal":"Kangla, Manipuri dance and valley cultural traditions.","Bishnupur":"Temples, handloom and the heritage landscape of Manipur.","Churachandpur":"Hill communities, handloom and local food traditions.","Ukhrul":"Tangkhul cultural landscapes, forests and mountain traditions.","Shillong":"Khasi culture, music, colonial-era spaces and hill-city life.","Cherrapunji":"Rainforest landscapes, living root bridges and Khasi traditions.","Jowai":"Jaintia heritage, monoliths and river landscapes.","Tura":"Garo culture, hills and community festivals.","Aizawl":"Mizo hill-city life, weaving and bamboo craft.","Lunglei":"Mountain landscapes, bamboo craft and local community life.","Champhai":"Borderland hills, vineyards and Mizo cultural traditions.","Kolasib":"Forests, rivers and bamboo-linked local livelihoods.","Kohima":"Naga heritage, war history, craft and village traditions.","Dimapur":"Market culture, Naga craft and a major regional gateway.","Mokokchung":"Ao Naga traditions, weaving and village culture.","Mon":"Konyak heritage, wood carving and village traditions.","Gangtok":"Monasteries, Himalayan views and Sikkimese food culture.","Pelling":"Monasteries, mountain views and West Sikkim heritage.","Namchi":"Monasteries, pilgrimage and southern Sikkim landscapes.","Mangan":"North Sikkim mountain routes and local village culture.","Agartala":"Ujjayanta Palace, royal heritage and Tripura craft.","Unakoti":"Rock-cut reliefs and forest-edge heritage.","Dharmanagar":"Northern Tripura markets, forests and regional culture.","Dehradun":"Doon Valley, institutional heritage and Himalayan gateways.","Haridwar":"Ganga riverfront, pilgrimage routes and ritual traditions.","Nainital":"Lake town, colonial-era hill heritage and Kumaoni culture.","Almora":"Kumaoni craft, temples and hill-town traditions.","Visakhapatnam":"Coastal city heritage, beaches and Andhra food culture.","Vijayawada":"Krishna riverfront, temple routes and Andhra culinary traditions.","Tirupati":"Temple pilgrimage, crafts and regional food traditions.","Kakinada":"Coastal Andhra food, port history and nearby cultural landscapes.","Tawang":"Monastery heritage, high mountain landscapes and Monpa traditions.","Itanagar":"Hill-city life, tribal culture and gateway routes.","Ziro":"Apatani cultural landscapes, paddy fields and community traditions.","Pasighat":"Siang river landscapes and Adi cultural traditions.","Raipur":"Urban Chhattisgarh, markets and regional craft connections.","Bastar":"Tribal craft, metalwork and forest cultural landscapes.","Bilaspur":"River landscapes, local markets and Chhattisgarh traditions.","Jagdalpur":"Bastar craft gateway and cultural performance traditions.","Gurugram":"Modern urban culture alongside nearby rural traditions.","Panipat":"Textile heritage, historic battles and craft markets.","Hisar":"Historic fortifications and Haryana agrarian culture.","Kurukshetra":"Mahabharata-associated pilgrimage landscapes and museums."};
function enrichDistrictFacts(){(window.SUTRA_EXTRA_STATES||[]).forEach(s=>s.districts.forEach(d=>{const f=SUTRA_DISTRICT_FACTS[d.name];if(f){d.heritage=f;d.overview=d.overview+' '+f}}))}
enrichDistrictFacts();
function mergeExpandedIndiaData(){
 const base=window.SUTRA_DATA?.states||[];
 const map=new Map(base.map(s=>[s.name,s]));
 SUTRA_EXTRA_STATES.forEach(extra=>{
   const old=map.get(extra.name);
   if(old){old.districts=extra.districts;old.image=extra.image;old.sourceName=extra.sourceName;old.sourceUrl=extra.sourceUrl;}
   else {map.set(extra.name,extra);}
 });
 if(window.SUTRA_DATA) window.SUTRA_DATA.states=[...map.values()];
 window.SUTRA_DISTRICTS=Object.fromEntries(SUTRA_EXTRA_STATES.map(s=>[s.name,s.districts]));
}
mergeExpandedIndiaData();

