function mergeExpandedExperiences(){if(!window.SUTRA_DATA)return;const foodKey=new Map(SUTRA_DATA.food.map(x=>[x.name+'|'+x.state+'|'+x.city,x]));SUTRA_EXTRA_FOOD.forEach(x=>{const key=x.name+'|'+x.state+'|'+x.city;const old=foodKey.get(key);if(old)Object.assign(old,x);else{SUTRA_DATA.food.push(x);foodKey.set(key,x)}});const eventLinks={ 'Jaipur Heritage Nights':'https://www.tourism.rajasthan.gov.in/fairs-and-festivals.html','Deccan Food & Craft Walk':'https://tourism.telangana.gov.in/events','Konark Craft Mela':'https://odishatourism.gov.in/content/tourism/en.html','Varanasi River Arts Evening':'https://www.uptourism.gov.in/','Mysuru Living Heritage Week':'https://karnatakatourism.org/','Kolkata Artisan Sunday':'https://wbtourism.gov.in/' };SUTRA_DATA.events.forEach(x=>{if(!x.website&&eventLinks[x.name]){x.website=eventLinks[x.name];x.websiteLabel='Open official event page'}});const eventKeys=new Set(SUTRA_DATA.events.map(x=>x.name+'|'+x.state+'|'+x.city));SUTRA_EXTRA_EVENTS.forEach(x=>{const key=x.name+'|'+x.state+'|'+x.city;if(!eventKeys.has(key)){SUTRA_DATA.events.push(x);eventKeys.add(key)}});}
mergeExpandedExperiences();